<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Throwable; use Pterodactyl\Models\User; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Models\Permission; use Illuminate\Validation\ValidationException; use Pterodactyl\Services\Dezerx\EggSwitcher; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\EggSwitchRequest; class EggSwitcherController extends ClientApiController { public function __construct(private readonly EggSwitcher $switcher) { parent::__construct(); } public function index(AddonRequest $request, Server $server): JsonResponse { $server->loadMissing('egg.nest'); return new JsonResponse([ 'current' => [ 'uuid' => (string) $server->egg?->uuid, 'name' => (string) $server->egg?->name, 'nest' => (string) $server->egg?->nest?->name, 'image' => $server->image, ], 'targets' => $this->switcher->targets($server), 'offered' => $this->switcher->offered($server), 'blocked' => $this->switcher->blocked($server, $request->user()), 'options' => $this->options($server, $request->user()), ]); } public function update(EggSwitchRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'egg' => ['required', 'string', 'max:64'], 'startup' => ['sometimes', 'boolean'], 'reinstall' => ['sometimes', 'boolean'], 'wipe' => ['sometimes', 'boolean'], ]); $egg = $this->switcher->target((string) $data['egg'], $server); if ($egg === null) { return new JsonResponse([ 'errors' => [['code' => 'UnknownEgg', 'detail' => 'That is not an egg this panel offers as a switch.']], ], 422); } $blocked = $this->switcher->blocked($server, $request->user()); if ($blocked !== null) { return new JsonResponse([ 'errors' => [['code' => 'ServerBusy', 'detail' => $blocked]], ], 409); } if ($egg->id === $server->egg_id) { return new JsonResponse([ 'errors' => [['code' => 'SameEgg', 'detail' => 'This server already runs that egg.']], ], 422); } $forced = $this->switcher->forced(); $startup = $forced['startup'] || (bool) ($data['startup'] ?? true); $reinstall = $forced['reinstall'] || (bool) ($data['reinstall'] ?? true); $wipe = $reinstall && ($forced['wipe'] || (bool) ($data['wipe'] ?? false)); if ($wipe && !$forced['wipe'] && !$request->user()->can(Permission::ACTION_FILE_DELETE, $server)) { return new JsonResponse([ 'errors' => [['code' => 'WipeNotAllowed', 'detail' => 'Deleting the server\'s files needs permission to delete files.']], ], 403); } try { $this->switcher->switch($server, $egg, $startup, $reinstall, $wipe); } catch (ValidationException $exception) { return new JsonResponse([ 'errors' => [[ 'code' => 'EggDefaults', 'detail' => 'That egg refused its own default values, so the switch was not made: ' . implode(' ', $exception->validator->errors()->all()), ]], ], 422); } catch (Throwable $exception) { return new JsonResponse([ 'errors' => [['code' => 'SwitchFailed', 'detail' => $exception->getMessage()]], ], 500); } Activity::event('server:egg.switch') ->property([ 'egg' => $egg->name, 'uuid' => $egg->uuid, 'startup' => $startup, 'reinstall' => $reinstall, 'wipe' => $wipe, ]) ->log(); return new JsonResponse([ 'egg' => $egg->uuid, 'reinstalled' => $reinstall, 'message' => $reinstall ? $server->name . ' is being rebuilt as ' . $egg->name . '. The console shows the install as it runs.' : $server->name . ' now runs ' . $egg->name . '. Nothing was reinstalled, so its files are as they were.', ], 202); } private function options(Server $server, User $user): array { $forced = $this->switcher->forced(); return [ 'startup' => $forced['startup'] ? 'force' : 'choose', 'reinstall' => $forced['reinstall'] ? 'force' : 'choose', 'wipe' => $forced['wipe'] ? 'force' : ($user->can(Permission::ACTION_FILE_DELETE, $server) ? 'choose' : 'denied'), ]; } } 